import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create group for the sprite element
  const group = new THREE.Group();

  // Atlas region: 512x320 pixels at (0, 0)
  // Assuming atlas is 2048x2048 (standard power-of-2)
  const atlasSize = 2048;
  const regionX = 0;
  const regionY = 0;
  const regionW = 512;
  const regionH = 320;

  // UV bounds for this region
  const uvMinX = regionX / atlasSize;
  const uvMinY = regionY / atlasSize;
  const uvMaxX = (regionX + regionW) / atlasSize;
  const uvMaxY = (regionY + regionH) / atlasSize;

  // Plane geometry: aspect ratio 512:320 = 1.6:1
  // Scale to fit nicely in scene (headline-sized)
  const width = 3.2; // ~headline scale in scene units
  const height = width * (regionH / regionW); // 2.0
  const geometry = new THREE.PlaneGeometry(width, height);

  // Adjust UVs to the atlas region
  const positions = geometry.attributes.position;
  const uvAttribute = geometry.attributes.uv;

  for (let i = 0; i < uvAttribute.count; i++) {
    let u = uvAttribute.getX(i);
    let v = uvAttribute.getY(i);
    // Map [0,1] to atlas region
    u = uvMinX + u * (uvMaxX - uvMinX);
    v = uvMinY + v * (uvMaxY - uvMinY);
    uvAttribute.setXY(i, u, v);
  }
  uvAttribute.needsUpdate = true;

  // Load the ceramic grain texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // TSL-based material with proper atlas UV mapping
  const material = new MeshBasicNodeMaterial({
    side: THREE.DoubleSide,
    transparent: true,
    toneMapped: false,
  });

  // Create mesh (material will be updated once texture loads)
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Update material with texture once loaded
  texturePromise.then((texture) => {
    texture.minFilter = THREE.LinearFilter;
    texture.magFilter = THREE.LinearFilter;
    // material.colorNode is set via map, but for NodeMaterial we pass color
    material.map = texture;
    material.needsUpdate = true;
  });

  // Create text content: "Features" headline
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const featuresTitleItem = textItems.find((item) => item.text === 'Features') || {
    text: 'Features',
    role: 'headline',
  };

  const titleText = ctx.fontAtlas.createText(featuresTitleItem.text, {
    fontSize: 96,
    color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
    align: 'center',
  });

  // Position text above the grain plane (z offset for layering)
  titleText.position.z = 0.1;
  group.add(titleText);

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (mesh.material.map) {
      mesh.material.map.dispose();
    }
  };

  return group;
}
